public extension View {
    func codexAutomationID(_ id: AutomationID) -> some View {
        accessibilityIdentifier(id.rawValue)
    }

    @ViewBuilder
    func codexAutomationID(_ id: AutomationID?) -> some View {
        if let id {
            codexAutomationID(id)
