struct DockSwipeActionRow<Content: View>: View {
    let row: DockRowViewModel
    let actionID: AutomationID
    let resetToken: RenderRevision
    let onTogglePinned: () -> Void
    let canOpen: Bool
    let onOpen: () -> Void
    @ViewBuilder var content: () -> Content
    @State private var offset: CGFloat = 0

    private let actionWidth: CGFloat = 86

    var body: some View {
        ZStack(alignment: .trailing) {
            if offset != 0 {
                swipeButton
            }

            content()
                .offset(x: offset)
        }
        .contentShape(Rectangle())
        .simultaneousGesture(dragGesture)
        .onTapGesture(perform: handleTap)
        .accessibilityElement(children: .contain)
        .accessibilityLabel(row.title)
        .accessibilityValue(row.automationValue)
        .accessibilityAddTraits(canOpen ? .isButton : [])
        .accessibilityAction {
            handleTap()
        }
        .codexAutomationID(AutomationID.Dock.row(hostID: row.id.hostID, threadID: row.id.threadID))
        .id(row.id)
        .onChange(of: row.id) { _, _ in
            closeAction()
        }
        .onChange(of: row.isPinned) { _, _ in
            closeAction()
        }
        .onChange(of: resetToken) { _, _ in
            closeAction()
        }
        .clipShape(RoundedRectangle(cornerRadius: 8, style: .continuous))
    }

    private var dragGesture: some Gesture {
        DragGesture(minimumDistance: 18, coordinateSpace: .local)
            .onChanged(updateOffset)
            .onEnded(finishDrag)
    }

    private var swipeButton: some View {
        Button(role: row.isPinned ? .destructive : nil) {
            closeAction()
            onTogglePinned()
        } label: {
            Label(row.isPinned ? "Unpin" : "Pin", systemImage: row.isPinned ? "pin.slash" : "pin.fill")
                .font(.caption.weight(.semibold))
                .labelStyle(.titleAndIcon)
                .frame(width: actionWidth)
                .frame(maxHeight: .infinity)
        }
        .buttonStyle(.plain)
        .foregroundStyle(.white)
        .background(row.isPinned ? Color.red : Color.blue)
        .codexAutomationID(actionID)
    }

    private func updateOffset(_ value: DragGesture.Value) {
        guard abs(value.translation.width) > abs(value.translation.height) else {
            return
        }
        offset = min(0, max(-actionWidth, value.translation.width))
    }

    private func finishDrag(_ value: DragGesture.Value) {
        let shouldOpen = value.translation.width < -(actionWidth * 0.35)
        withAnimation(.spring(response: 0.25, dampingFraction: 0.9)) {
            offset = shouldOpen ? -actionWidth : 0
        }
    }

    private func handleTap() {
        if offset != 0 {
            closeAction()
        } else if canOpen {
            onOpen()
        }
    }

    private func closeAction() {
        withAnimation(.spring(response: 0.25, dampingFraction: 0.9)) {
            offset = 0
        }
    }
}

struct DockPinnedSectionView<RowContent: View>: View {
    let projection: DockCardProjection
    @Binding var isCollapsed: Bool
    let onMove: ([DockRowViewModel]) -> Void
    let onUnpin: (DockRowViewModel) -> Void
    let onOpen: (DockRowViewModel) -> Void
    @ViewBuilder let rowContent: (DockRowViewModel) -> RowContent

    var body: some View {
        VStack(alignment: .leading, spacing: 8) {
            Button {
                withAnimation(.spring(response: 0.25, dampingFraction: 0.9)) {
                    isCollapsed.toggle()
                }
            } label: {
                HStack(spacing: 8) {

            ?? renderSnapshot.snapshot.hostIdentityResolver.state(
                forAlias: hostID,
                in: renderSnapshot.snapshot.hostStates
            )
    }

    private func contextualHostStates(in snapshot: DockSnapshot) -> [DockHostStateViewModel] {
        snapshot.hostStates.filter { hostState in
            hostState.status == .checking || hostState.status.isPartial || hostState.status.isUnavailable
        }
    }

    private func hostStatusList(
        _ hostStates: [DockHostStateViewModel],
        stateTitle: String
    ) -> some View {
        VStack(alignment: .leading, spacing: 12) {
            Text(stateTitle)
                .font(.subheadline.weight(.semibold))
                .foregroundStyle(.secondary)
            LazyVStack(spacing: 10) {
                ForEach(hostStates) { hostState in
                    hostContextRow(
                        hostState,
                        automationID: AutomationID.Dock.hostSummary(hostID: hostState.host.id)
                    )
                }
            }
            if hostStates.contains(where: { $0.status == .checking }) {
                Text("Waiting for relay response")
                    .font(.caption)
                    .foregroundStyle(.secondary)
                    .codexAutomationID(AutomationID.Dock.state(.loading))
            }
        }
    }

    @ViewBuilder
    private func hostContextRow(
        _ hostState: DockHostStateViewModel,
        automationID: AutomationID? = nil
    ) -> some View {
        if hostState.status.isUnavailable {
            hostFailureRow(hostState, automationID: automationID)
        } else {
            HostLoadingRow(hostState: hostState)
                .codexAutomationID(automationID)
        }
    }

    private func hostFailureRow(
        _ hostState: DockHostStateViewModel,
        automationID: AutomationID? = nil
    ) -> some View {
        HostFailureRow(
            hostState: hostState,
            onRetry: {
                Task {
                    await store.refresh()
                }
            },
            onOpenRelaySettings: onOpenRelaySettings
        )
        .codexAutomationID(automationID)
    }

    @ViewBuilder
    private func rowContextMenu(_ row: DockRowViewModel) -> some View {
        DockRowContextMenu(
            row: row,
            store: store,
            onArchiveSucceeded: onArchiveSucceeded
        )
    }

