import Foundation

public struct AppServerThreadDetailSessionFactory: ThreadDetailSessionMaking {
    private let makeClient: @Sendable (
        DockRelayEndpoint,
        (any AppForegroundWorkGating)?
    ) -> AppServerClient

    public init() {
        self.makeClient = { endpoint, foregroundWorkGate in
            AppServerClient(
                webSocketURL: endpoint.webSocketURL,
                bearerToken: nil,
                connectionPolicy: .liveDetail,
                foregroundWorkGate: foregroundWorkGate
            )
        }
    }

    public init(makeClient: @escaping @Sendable (DockRelayEndpoint) -> AppServerClient) {
        self.makeClient = { endpoint, _ in
            makeClient(endpoint)
        }
    }

    public func makeSession(for host: DockHostConfiguration) -> any ThreadDetailSession {
        makeSession(for: host, foregroundWorkGate: nil)
    }

    public func makeSession(
        for host: DockHostConfiguration,
        foregroundWorkGate: (any AppForegroundWorkGating)?
    ) -> any ThreadDetailSession {
        let makeClient = self.makeClient
        return AppServerThreadDetailSession(
            host: host,
            makeClient: { endpoint in
                makeClient(endpoint, foregroundWorkGate)
            }
        )
    }
}

private actor AppServerThreadDetailSession: ThreadDetailSession {
    nonisolated let connectionStates: AsyncStream<AppServerConnectionState>
    nonisolated let notifications: AsyncStream<JSONRPCNotification>
    nonisolated let serverRequests: AsyncStream<JSONRPCRequest>

    private let host: DockHostConfiguration
    private let makeClient: @Sendable (DockRelayEndpoint) -> AppServerClient
    private let connectionStateContinuation: AsyncStream<AppServerConnectionState>.Continuation
    private let notificationContinuation: AsyncStream<JSONRPCNotification>.Continuation
    private let serverRequestContinuation: AsyncStream<JSONRPCRequest>.Continuation
    private var client: AppServerClient?
    private var connectionStateTask: Task<Void, Never>?
    private var notificationTask: Task<Void, Never>?
    private var serverRequestTask: Task<Void, Never>?

    init(
        host: DockHostConfiguration,
        makeClient: @escaping @Sendable (DockRelayEndpoint) -> AppServerClient
    ) {
        self.host = host
        self.makeClient = makeClient
        let connectionStates = AsyncStream.makeStream(of: AppServerConnectionState.self)
        let notifications = AsyncStream.makeStream(of: JSONRPCNotification.self)
        let serverRequests = AsyncStream.makeStream(of: JSONRPCRequest.self)
        self.connectionStates = connectionStates.stream
        self.connectionStateContinuation = connectionStates.continuation
        self.notifications = notifications.stream
        self.notificationContinuation = notifications.continuation
        self.serverRequests = serverRequests.stream
        self.serverRequestContinuation = serverRequests.continuation
        self.connectionStateContinuation.yield(.idle)
    }

    deinit {
        connectionStateTask?.cancel()
        notificationTask?.cancel()
        serverRequestTask?.cancel()
        connectionStateContinuation.finish()
        notificationContinuation.finish()
        serverRequestContinuation.finish()
    }

    func connectAndInitialize(
        params: InitializeParams,
        timeout: Duration
    ) async throws -> InitializeResponse {
        connectionStateContinuation.yield(.connecting)
        let connection = try await AppServerHostConnector(makeClient: makeClient)
            .connectAndInitialize(for: host, params: params, timeout: timeout)
        client = connection.client
        startForwarding(from: connection.client)
        connectionStateContinuation.yield(.connected)
        return connection.initializeResponse
    }

    func threadRead(
        params: ThreadReadParams,
        timeout: Duration
    ) async throws -> ThreadReadResponseDTO {
        try await requireClient().threadRead(
            params: params,
            timeout: timeout,
            observabilityContext: context(for: AppServerMethods.threadRead)
        )
    }

    func threadTurnsList(
        params: ThreadTurnsListParams,
        timeout: Duration
    ) async throws -> ThreadTurnsListResponseDTO {
        try await requireClient().threadTurnsList(
            params: params,
            timeout: timeout,
            observabilityContext: context(for: AppServerMethods.threadTurnsList)
        )
    }

    func threadResume(
        params: ThreadResumeParams,
        timeout: Duration
    ) async throws -> ThreadResumeResponseDTO {
        try await requireClient().threadResume(
            params: params,
            timeout: timeout,
            observabilityContext: context(for: AppServerMethods.threadResume)
        )
    }

    func turnStart(params: TurnStartParams, timeout: Duration) async throws -> TurnStartResponseDTO {
        try await requireClient().turnStart(
            params: params,
            timeout: timeout,
            observabilityContext: context(for: AppServerMethods.turnStart)
        )
    }

    func turnSteer(params: TurnSteerParams, timeout: Duration) async throws -> TurnSteerResponseDTO {
        try await requireClient().turnSteer(
            params: params,
            timeout: timeout,
            observabilityContext: context(for: AppServerMethods.turnSteer)
        )
    }

    func sendResponse(id: JSONRPCRequestID, result: JSONValue) async throws {
        try await requireClient().sendResponse(id: id, result: result)
    }

    func disconnect() async {
        connectionStateTask?.cancel()
        notificationTask?.cancel()
        serverRequestTask?.cancel()
        let client = client
        self.client = nil
        await client?.disconnect()
        connectionStateContinuation.finish()
        notificationContinuation.finish()
        serverRequestContinuation.finish()
    }

    private func startForwarding(from client: AppServerClient) {
        connectionStateTask?.cancel()
        notificationTask?.cancel()
        serverRequestTask?.cancel()

        let connectionStateContinuation = connectionStateContinuation
        connectionStateTask = Task { [client] in
            for await state in client.connectionStates {
                connectionStateContinuation.yield(state)
            }
        }

        let notificationContinuation = notificationContinuation
        notificationTask = Task { [client] in
            for await notification in client.notifications {
                notificationContinuation.yield(notification)
            }
        }

        let serverRequestContinuation = serverRequestContinuation
        serverRequestTask = Task { [client] in
            for await request in client.serverRequests {
                serverRequestContinuation.yield(request)
            }
        }
    }

    private func requireClient() throws -> AppServerClient {
        guard let client else {
            throw AppServerClientError.notConnected(.idle)
        }
        return client
    }

    private func context(for route: String) -> AppServerRequestObservabilityContext {
        AppServerRequestObservabilityContext(
            configuredHostID: host.id,
            route: route,
            store: .shared
        )
    }
}

    case .offline(let reason):
        markLiveSessionStale(reason)
    case .error(let message):
        markLiveSessionStale(message)
    case .closed(let reason):
        markLiveSessionStale(reason)
    case .idle, .connecting:
        return
    }
}

private func message(from connectionState: AppServerConnectionState) -> String {
    switch connectionState {
    case .idle:
        return "Waiting for connection."
    case .connecting:
        return "Connecting."
    case .connected:
        return "Connected."
    case .reconnecting(_, let reason):
        return reason
    case .offline(let reason):
        return reason
    case .error(let message):
        return message
    case .closed(let reason):
        return reason
    }
}

private func readFullThread(session: any ThreadDetailSession) async throws -> FullThreadRead {
    let startedAt = Date()
    let signpostState = DockSignpost.threadDetail.beginInterval("thread.readFull")
    defer {
        DockSignpost.threadDetail.endInterval("thread.readFull", signpostState)
    }
    let readResponse = try await session.threadRead(
        params: ThreadReadParams(threadId: row.id.threadID, includeTurns: false),
        timeout: CodexDockConstants.AppServer.defaultRequestTimeout
    )
    let turns = try await readAllTurns(session: session)
    DockLog.threadDetail.info("thread full read finished thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) turns=\(turns.count, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
    return FullThreadRead(
        thread: readResponse.thread.replacingTurns(turns),
        turns: turns
    )
}

private func readAllTurns(session: any ThreadDetailSession) async throws -> [JSONValue] {
    var cursor: String?
    var seenCursors = Set<String>()
    var turns: [JSONValue] = []

    repeat {
        let response = try await session.threadTurnsList(
            params: ThreadTurnsListParams(
                threadId: row.id.threadID,
                cursor: cursor,
                limit: Self.turnPageLimit
            ),
            timeout: CodexDockConstants.AppServer.defaultRequestTimeout
        )
        turns.append(contentsOf: response.data)

        guard let nextCursor = response.nextCursor, !nextCursor.isEmpty else {
            cursor = nil
            break
        }
        guard seenCursors.insert(nextCursor).inserted else {
            throw ThreadDetailStoreError.repeatedTurnsCursor(nextCursor)
        }
        cursor = nextCursor
    } while cursor != nil

    return turns
}

private func resumeCompactThread(
    session: any ThreadDetailSession,
    turns: [JSONValue]
) async throws -> ThreadDTO {
    let startedAt = Date()
    let signpostState = DockSignpost.threadDetail.beginInterval("thread.resume")
    defer {
        DockSignpost.threadDetail.endInterval("thread.resume", signpostState)
    }
    let resumeResponse = try await session.threadResume(
        params: ThreadResumeParams(threadId: row.id.threadID, excludeTurns: true),
        timeout: CodexDockConstants.AppServer.defaultRequestTimeout
    )
    DockLog.threadDetail.info("thread resume finished thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) turns=\(turns.count, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
    return resumeResponse.thread.replacingTurns(turns)
}

private func startRehydrateAfterReconnectIfNeeded() {
    guard !isClosing,
          recoveryTask == nil,
          case .loaded = state,
          case let .reconnecting(reason) = liveState,
          let session else {
        return
    }

    recoveryTask = Task { [weak self] in
        await self?.rehydrateAfterReconnect(session: session, reason: reason)
    }
}

private func rehydrateAfterReconnect(
    session: any ThreadDetailSession,
    reason: String
) async {
    guard !isClosing, case .loaded = state else {
        recoveryTask = nil
        return
    }

    liveState = .reconnecting(reason)
    DockLog.threadDetail.notice("thread detail rehydrate started thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) reason=\(DockLog.redacted(reason), privacy: .public)")
    publishLoaded()

    do {
        let fullRead = try await readFullThread(session: session)
        let liveThread = try await resumeCompactThread(session: session, turns: fullRead.turns)
        try await mergeEvents(from: liveThread, liveState: .live)
        DockLog.threadDetail.notice("thread detail rehydrate finished thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) events=\(self.events.count, privacy: .public)")
    } catch {
        liveState = .stale(message(from: error))
        publishLoaded()
        DockLog.threadDetail.warning("thread detail rehydrate failed thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
    }

    recoveryTask = nil
}

private func markLiveSessionReconnecting(_ message: String) {
    guard !isClosing, case .loaded = state else {
        return
    }
    switch liveState {
    case .closed:
        return
    case .connecting, .reconnecting, .live, .stale:
        liveState = .reconnecting(message)
        DockLog.threadDetail.notice("thread detail reconnecting thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) reason=\(DockLog.redacted(message), privacy: .public)")
        publishLoaded()
    }
}

private func replaceEvents(from thread: ThreadDTO, liveState: ThreadDetailLiveState) async throws {
    let snapshot = try await dataEngine.replace(
        from: thread,
        expectedThreadID: row.id.threadID
    )
    applyDataSnapshot(snapshot)
    self.liveState = liveState
    publishLoaded()
}

private func mergeEvents(from thread: ThreadDTO, liveState: ThreadDetailLiveState) async throws {
    let snapshot = try await dataEngine.merge(
        from: thread,
        expectedThreadID: row.id.threadID
    )
    applyDataSnapshot(snapshot)
    self.liveState = liveState
    publishLoaded()
}

private func handle(notification: JSONRPCNotification) async {
    guard let dataSnapshot = await dataEngine.apply(
        notification: notification,
        expectedThreadID: row.id.threadID,
        now: now()
    ) else {
        return
    }
    applyDataSnapshot(dataSnapshot)

    resolveRequestCard(from: notification)

    if notification.method == "thread/closed" {
        liveState = .closed
    } else {
        liveState = .live
    }
    DockLog.threadDetail.debug("thread notification handled method=\(notification.method, privacy: .public) thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) live_state=\(self.liveState.logDescription, privacy: .public)")

    publishLoaded()
}

private func handle(request: JSONRPCRequest) async {
    guard let dataSnapshot = await dataEngine.apply(
        request: request,
        expectedThreadID: row.id.threadID,
        now: now()
    ) else {
        return
    }
    applyDataSnapshot(dataSnapshot)

    liveState = .live
    upsertRequestCard(ServerRequestCard.make(from: request, now: now()))
    DockLog.threadDetail.notice("server request received method=\(request.method, privacy: .public) request_id=\(DockLog.publicID(request.id), privacy: .public) thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public)")
    publishLoaded()
}

private func markLiveSessionStale(_ message: String) {
    guard !isClosing, case .loaded = state else {
        return
    }
    switch liveState {
    case .closed, .stale:
        return
    case .connecting, .reconnecting, .live:
        break
    }
    liveState = .stale(message)
    DockLog.threadDetail.warning("thread detail marked stale thread_id=\(DockLog.publicID(self.row.id.threadID), privacy: .public) reason=\(DockLog.redacted(message), privacy: .public)")
    publishLoaded()
}

import Foundation

public struct ThreadDetailDataSnapshot: Equatable, Sendable {
    public let events: [ThreadEvent]
    public let activeTurnID: String?

    public init(events: [ThreadEvent], activeTurnID: String?) {
        self.events = events
        self.activeTurnID = activeTurnID
    }
}

public actor ThreadDetailDataEngine {
    private var index = ThreadEventIndex()
    private var activeTurnID: String?

    public init() {}

    public func replace(
        from thread: ThreadDTO,
        expectedThreadID: String
    ) throws -> ThreadDetailDataSnapshot {
        try validate(thread: thread, expectedThreadID: expectedThreadID)
        let signpostState = DockSignpost.rendering.beginInterval(RenderSignpostName.threadModelNormalize)
        let events = ThreadEventNormalizer.events(from: thread)
        DockSignpost.rendering.endInterval(RenderSignpostName.threadModelNormalize, signpostState)
        index.replace(with: events)
        activeTurnID = Self.activeTurnID(from: thread)
        return snapshot()
    }

    public func merge(
        from thread: ThreadDTO,
        expectedThreadID: String
    ) throws -> ThreadDetailDataSnapshot {
        try validate(thread: thread, expectedThreadID: expectedThreadID)
        let signpostState = DockSignpost.rendering.beginInterval(RenderSignpostName.threadModelNormalize)
        let events = ThreadEventNormalizer.events(from: thread)
        DockSignpost.rendering.endInterval(RenderSignpostName.threadModelNormalize, signpostState)
        for event in events {
            index.appendOrMerge(event)
        }
        activeTurnID = Self.activeTurnID(from: thread)
        return snapshot()
    }

    public func apply(
        notification: JSONRPCNotification,
        expectedThreadID: String,
        now: Date
    ) -> ThreadDetailDataSnapshot? {
        guard ThreadEventNormalizer.threadId(from: notification) == expectedThreadID else {
            return nil
        }
        updateActiveTurn(from: notification)
        if let event = ThreadEventNormalizer.event(from: notification, now: now) {
            index.appendOrMerge(event)
        }
        return snapshot()
    }

    public func apply(
        request: JSONRPCRequest,
        expectedThreadID: String,
        now: Date
    ) -> ThreadDetailDataSnapshot? {
        guard ThreadEventNormalizer.threadId(from: request) == expectedThreadID else {
            return nil
        }
        index.appendOrMerge(ThreadEventNormalizer.event(from: request, now: now))
        return snapshot()
    }

    public func setActiveTurnID(_ activeTurnID: String?) {
        self.activeTurnID = activeTurnID
    }

    public func currentSnapshot() -> ThreadDetailDataSnapshot {
        snapshot()
    }

    private func snapshot() -> ThreadDetailDataSnapshot {
        ThreadDetailDataSnapshot(
            events: index.eventsNewestFirst(),
            activeTurnID: activeTurnID
        )
    }

    private func validate(thread: ThreadDTO, expectedThreadID: String) throws {
        guard thread.id == expectedThreadID else {
            throw ThreadDetailStoreError.threadMismatch(
                expected: expectedThreadID,
                actual: thread.id ?? "missing"
            )
        }
    }

    private func updateActiveTurn(from notification: JSONRPCNotification) {
        guard let params = notification.params?.objectValue else {
            return
        }

        switch notification.method {
        case "turn/started":
            if let turn = params["turn"] {
                activeTurnID = Self.turnID(from: turn)
            }
        case "turn/completed":
            if let turn = params["turn"], activeTurnID == Self.turnID(from: turn) {
                activeTurnID = nil
            }
        default:
            return
        }
    }

    private static func activeTurnID(from thread: ThreadDTO) -> String? {
        thread.turns?
            .compactMap { turn -> String? in
                guard let object = turn.objectValue,
                      object["status"]?.stringValue == "inProgress" else {
                    return nil
                }
                return object["id"]?.stringValue
            }
            .last
    }

    private static func turnID(from turn: JSONValue) -> String? {
        turn.objectValue?["id"]?.stringValue
    }
}

struct ThreadEventIndex: Sendable {
    private var events: [ThreadEvent] = []

    mutating func replace(with events: [ThreadEvent]) {
        self.events = ThreadEventDisplayOrder.newestFirst(events)
    }

    mutating func appendOrMerge(_ event: ThreadEvent) {
        guard let index = events.firstIndex(where: { $0.id == event.id }) else {
            appendOrMergeByStreamItem(event)
            return
        }

        let mergedEvent: ThreadEvent
        if events[index].isStreamingDelta, event.isStreamingDelta, events[index].kind == event.kind {
            var existing = events[index]
            existing.body += event.body
            mergedEvent = existing
        } else {
            mergedEvent = event
        }
        events.remove(at: index)
        insertInOrder(mergedEvent)
    }

    func eventsNewestFirst() -> [ThreadEvent] {
        events
    }

    private mutating func appendOrMergeByStreamItem(_ event: ThreadEvent) {
        guard let mergeKey = ThreadEventStreamMergeKey(event),
              let index = events.firstIndex(where: { ThreadEventStreamMergeKey($0) == mergeKey }) else {
            insertInOrder(event)
            return
        }

        let existing = events[index]
        let mergedEvent: ThreadEvent?
        if existing.isStreamingDelta, event.isStreamingDelta, existing.kind == event.kind {
            var next = existing
            next.body += event.body
            mergedEvent = next
        } else if existing.isStreamingDelta || !event.isStreamingDelta {
            mergedEvent = event
        } else {
            // Ignore late deltas after a full item snapshot has already arrived.
            mergedEvent = nil

    }

    let startedAt = Date()
    let signpostState = DockSignpost.dock.beginInterval("dock.reload")
    DockLog.dock.notice("dock stream reload started hosts=\(self.hosts.count, privacy: .public) show_loading=\(showLoading, privacy: .public)")
    isLoading = true
    defer {
        DockSignpost.dock.endInterval("dock.reload", signpostState)
        isLoading = false
    }

    let hostViewModels = hosts.map(DockHostViewModel.init)
    if showLoading {
        state = .loading(hostViewModels)
        screenStore.setLoading(hosts: hostViewModels)
        publishConnectivity(for: state)
    }

    do {
        localMetadata = try await metadataEngine.load()
        DockLog.persistence.debug("dock metadata loaded entries=\(self.localMetadata.count, privacy: .public)")
    } catch {
        localMetadata = [:]
        await metadataEngine.replace(localMetadata)
        DockLog.persistence.warning("dock metadata load failed error=\(DockLog.errorSummary(error), privacy: .public)")
    }

    await dataEngine?.updateLocalMetadata(localMetadata)
    await dataEngine?.ensureHosts()
    await synchronizeStreams()
    await migrateMetadataHostAliases()
    await publishSnapshot()
    if case let .loaded(snapshot) = state {
        DockLog.dock.notice("dock stream reload finished hosts=\(self.hosts.count, privacy: .public) rows=\(snapshot.rowCount, privacy: .public) duration_ms=\(DockLog.milliseconds(since: startedAt), privacy: .public)")
    }
}

private func synchronizeStreams() async {
    let validHostIDs = Set(hosts.map(\.id))
    for hostID in streamConnections.keys where !validHostIDs.contains(hostID) {
        streamTasks[hostID]?.cancel()
        streamTasks[hostID] = nil
        let connection = streamConnections.removeValue(forKey: hostID)
        await connection?.close()
    }

    for host in hosts {
        if let connection = streamConnections[host.id] {
            await resync(host: host, connection: connection)
        } else {
            await openStream(host: host)
        }
    }
}

private func openStream(host: DockHostConfiguration) async {
    guard let dataEngine else {
        return
    }

    await dataEngine.markChecking(host: host)
    await publishSnapshot()
    var openedConnection: (any ThreadCardStreamConnection)?
    do {
        let connection = try await streamClient.connect(to: host)
        openedConnection = connection
        streamConnections[host.id] = connection
        let snapshot = try await connection.subscribe()
        try await applySubscribedSnapshot(snapshot, host: host, connection: connection)
        startUpdateTask(host: host, connection: connection)
        await migrateMetadataHostAliases()
        await publishSnapshot()
    } catch {
        streamTasks[host.id]?.cancel()
        streamTasks[host.id] = nil
        streamConnections[host.id] = nil
        await openedConnection?.close()
        DockLog.dock.warning("dock stream open failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
        await dataEngine.markFailure(Self.mapRequestFailure(error), host: host)
        await publishSnapshot()
    }
}

private func resync(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) async {
    guard let dataEngine else {
        return
    }

    do {
        let snapshot = try await connection.resync()
        try await applyResyncSnapshot(snapshot, host: host)
        await migrateMetadataHostAliases()
        await publishSnapshot()
        let rowCount = await dataEngine.rowCount(for: host)
        DockLog.dock.notice("dock stream resync finished host_id=\(host.id, privacy: .public) seq=\(snapshot.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
    } catch {
        DockLog.dock.warning("dock stream resync failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
        await dataEngine.markFailure(Self.mapRequestFailure(error), host: host)
        await publishSnapshot()
    }
}

private func startUpdateTask(host: DockHostConfiguration, connection: any ThreadCardStreamConnection) {
    streamTasks[host.id]?.cancel()
    streamTasks[host.id] = Task { [weak self, host, connection] in
        do {
            for try await update in connection.updates() {
                await self?.handleStreamUpdate(update, host: host, connection: connection)
            }
            if !Task.isCancelled {
                await self?.handleStreamFailure(
                    DockRequestFailure.offline("Relay stream closed"),
                    host: host,
                    connection: connection
                )
            }
        } catch is CancellationError {
            return
        } catch {
            await self?.handleStreamFailure(error, host: host, connection: connection)
        }
    }
}

private func handleStreamUpdate(
    _ update: ThreadCardStreamUpdateDTO,
    host: DockHostConfiguration,
    connection: any ThreadCardStreamConnection
) async {
    guard let dataEngine else {
        return
    }

    let result = await dataEngine.applyUpdate(update, host: host)
    if case .needsResync(let reason) = result {
        DockLog.dock.warning("dock stream resync needed host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public)")
        await resync(host: host, connection: connection)
    } else {
        await migrateMetadataHostAliases()
        await publishSnapshot()
        let rowCount = await dataEngine.rowCount(for: host)
        DockLog.dock.info("dock stream update applied host_id=\(host.id, privacy: .public) update_kind=\(update.kind.rawValue, privacy: .public) seq=\(update.seq, privacy: .public) rows=\(rowCount, privacy: .public)")
        if let freshness = update.freshness,
           freshness.status != .fresh,
           rowCount > 0 {
            DockLog.dock.notice("dock stream rows retained host_id=\(host.id, privacy: .public) freshness=\(freshness.status.rawValue, privacy: .public) rows=\(rowCount, privacy: .public)")
        }
    }
}

private func applySubscribedSnapshot(
    _ snapshot: ThreadCardStreamUpdateDTO,
    host: DockHostConfiguration,
    connection: any ThreadCardStreamConnection
) async throws {
    guard let dataEngine else {
        return
    }

    switch await dataEngine.applySnapshot(snapshot, host: host) {
    case .applied:
        return
    case .needsResync(let reason):
        DockLog.dock.warning("dock stream subscribe snapshot rejected host_id=\(host.id, privacy: .public) reason=\(reason.rawValue, privacy: .public) seq=\(snapshot.seq, privacy: .public)")
        let resynced = try await connection.resync()
        try await applyResyncSnapshot(resynced, host: host)
    }
}

private func applyResyncSnapshot(
    _ snapshot: ThreadCardStreamUpdateDTO,
    host: DockHostConfiguration
) async throws {
    guard let dataEngine else {
        return
    }

    switch await dataEngine.applySnapshot(snapshot, host: host) {
    case .applied:
        return
    case .needsResync(let reason):
        throw DockRequestFailure.error("Dock stream resync returned incompatible data (\(reason.rawValue)).")
    }
}

private func handleStreamFailure(
    _ error: Error,
    host: DockHostConfiguration,
    connection: any ThreadCardStreamConnection
) async {
    DockLog.dock.warning("dock stream update failed host_id=\(host.id, privacy: .public) error=\(DockLog.errorSummary(error), privacy: .public)")
    streamConnections[host.id] = nil
    streamTasks[host.id] = nil
    await connection.close()
    await dataEngine?.markFailure(Self.mapRequestFailure(error), host: host)
    await publishSnapshot()
    let rowCount = await dataEngine?.rowCount(for: host) ?? 0
    if rowCount > 0 {
        DockLog.dock.notice("dock stream rows retained host_id=\(host.id, privacy: .public) freshness=offline rows=\(rowCount, privacy: .public)")
    }
    scheduleReconnect(host: host)
}

private func scheduleReconnect(host: DockHostConfiguration) {
    guard hosts.contains(where: { $0.id == host.id }) else {
        return
    }
    streamTasks[host.id] = Task { [weak self, host] in
        do {
            try await Task.sleep(for: self?.streamReconnectDelay ?? CodexDockConstants.Dock.autoRefreshInterval)
        } catch {
            return
        }
        await self?.openStream(host: host)
    }
}

private func closeStreams() async {
    streamTasks.values.forEach { $0.cancel() }
    streamTasks = [:]
    let connections = streamConnections
    streamConnections = [:]
    for connection in connections.values {
        await connection.close()
    }
}

private func publishSnapshot() async {
    guard !hosts.isEmpty else {
        return
    }
    guard let snapshot = await dataEngine?.snapshot(now: now) else {
        return
    }
    state = .loaded(snapshot)
    screenStore.publish(snapshot: snapshot)
    publishConnectivity(for: state)
}

private func migrateMetadataHostAliases() async {
    guard let resolver = await dataEngine?.hostIdentityResolver() else {
        return
    }
    do {
        let migratedMetadata = try await metadataEngine.migrateHostAliases(using: resolver)
        if migratedMetadata != localMetadata {
            DockLog.persistence.notice("dock metadata host aliases migrated entries=\(migratedMetadata.count, privacy: .public)")
        }
        localMetadata = migratedMetadata
        await dataEngine?.updateLocalMetadata(localMetadata)
    } catch {
        DockLog.persistence.warning("dock metadata host alias migration failed error=\(DockLog.errorSummary(error), privacy: .public)")
    }
}

private func publishConnectivity(for state: DockStoreState) {
    if connectivityEventSink == nil {
        connectivityReporter?.reportDockState(state)
    }
    recordConnectivityFacts(for: state)
}

private func recordConnectivityFacts(for state: DockStoreState) {
    guard let connectivityEventSink else {
        return
    }
    let events = connectivityEvents(for: state)
    guard !events.isEmpty else {
        return
    }
    Task {
        for event in events {
            await connectivityEventSink.record(event)
        }
    }
}

